import { useState, useCallback } from 'react';
import {
  Box,
  Stack,
  Heading,
  Text,
  Badge,
  Divider,
  SegmentedControl,
  Slider,
  Switch,
  Select,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'inter' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABEL: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [dense, setDense] = useState<boolean>(false);
  const [font, setFont] = useState<Font>('system');

  const emit = useCallback(
    (next: Partial<AppearanceSettings>) => {
      onChange?.({
        theme,
        scale,
        dense,
        font,
        ...next,
      });
    },
    [theme, scale, dense, font, onChange]
  );

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (value: boolean) => {
    setDense(value);
    emit({ dense: value });
  };

  const handleFontChange = (value: Font) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <Box className="jx-p-6" style={{ maxWidth: 480 }}>
      <Stack direction="row" align="center" justify="between" className="jx-mb-4">
        <Heading size="lg">Внешний вид</Heading>
        <Badge variant="subtle" color="accent">
          {THEME_LABEL[theme]}
        </Badge>
      </Stack>

      <Stack direction="column" gap="6">
        <Stack direction="column" gap="2">
          <Text size="sm" color="secondary">
            Тема
          </Text>
          <SegmentedControl
            value={theme}
            onChange={(value) => handleThemeChange(value as Theme)}
            options={[
              { value: 'light', label: 'Светлая' },
              { value: 'dark', label: 'Тёмная' },
              { value: 'system', label: 'Системная' },
            ]}
            fullWidth
          />
        </Stack>

        <Stack direction="column" gap="2">
          <Stack direction="row" align="center" justify="between">
            <Text size="sm" color="secondary">
              Масштаб интерфейса
            </Text>
            <Text size="sm" weight="medium">
              {scale}%
            </Text>
          </Stack>
          <Slider
            min={80}
            max={140}
            step={5}
            value={scale}
            onChange={handleScaleChange}
            aria-label="Масштаб интерфейса"
          />
        </Stack>

        <Stack direction="row" align="center" justify="between">
          <Stack direction="column" gap="1">
            <Text size="sm">Плотная вёрстка</Text>
            <Text size="xs" color="secondary">
              Уменьшает отступы и высоту строк
            </Text>
          </Stack>
          <Switch checked={dense} onChange={handleDenseChange} aria-label="Плотная вёрстка" />
        </Stack>

        <Divider />

        <Stack direction="column" gap="3">
          <Text size="sm" weight="medium" color="secondary">
            Ещё
          </Text>

          <Stack direction="row" align="center" justify="between">
            <Text size="sm">Шрифт</Text>
            <Select
              value={font}
              onChange={(value) => handleFontChange(value as Font)}
              options={[
                { value: 'system', label: 'Системный' },
                { value: 'inter', label: 'Inter' },
                { value: 'mono', label: 'Моноширинный' },
              ]}
              style={{ minWidth: 160 }}
            />
          </Stack>
        </Stack>
      </Stack>
    </Box>
  );
}

